static int NPCMENU_CanItemBeRepaired(D2UnitStrc * pUnit) {
    int nCurrentDurability;
    int nMaxStack;
    int nChargeCount;
    eD2ItemTypes eItemType = D2Common::ITEMS::Items::ITEM_GetItemData_wType(pUnit);
    if (eItemType == ITEMTYPE_Gold) {
      return 0;
    }

    uint32_t bCanRepair = D2Common::ITEMS::Items::ITEM_CanBeRepaired(pUnit);
    if (!bCanRepair) {
      return 0;
    }

    bCanRepair = D2Common::ITEMS::Items::ITEM_CheckIfItemHasDurability(pUnit);
    if (bCanRepair) {
      int32_t nMaxDurability;
      nMaxDurability = D2Common::Stats::StatsEx::GetTxtMaxDurability(pUnit);
      if (nMaxDurability) {
        nCurrentDurability = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_durability, 0);
        if (nCurrentDurability < nMaxDurability) {
          return 1;
        }
      }
    }

    int nIsStackable = D2Common::ITEMS::Items::IsStackable(pUnit);
    if (nIsStackable) {
      nCurrentDurability = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_quantity, 0);
      nMaxStack = D2Common::ITEMS::Items::ITEM_GetMaxStack(pUnit);
      if (nCurrentDurability < nMaxStack) {
        return 1;
      }
    }

    BOOL BVar1 = D2Common::ITEMS::Items::ITEMS_CheckChargedSkillFullyCharged(pUnit, (bool*)&nChargeCount);
    if (!(BVar1 && !nChargeCount)) {
      return 0;
    }

    return 1;
}

