static int32_t NPCMENU_FindMenuIndexByNpcId(D2UnitStrc * pNpcUnit) {
    if (!pNpcUnit) {
      return -1;
    }

    int nMenuIndex = 0;
    if (NPC::D2NpcMenuOptionsCount <= 0) {
      return 0;
    }

    do {
      if (NPC::D2NpcMenuOptions[nMenuIndex].nNpcId == pNpcUnit->nClassId) {
        return nMenuIndex;
      }

      nMenuIndex++;
    } while (nMenuIndex < NPC::D2NpcMenuOptionsCount);

    return 0;
}

