// A two-liner:
// NPCMENU_SendCainIdentifyItems('\x01', g_nNpcTradeMenuState->nGossip). In the callee
// @004b40d0 a non-zero first argument makes it re-read g_nNpcTradeMenuState->nGossip and
// ignore the passed id, so this menu entry simply re-shows the NPC's current gossip line.
// 004b41e0 is the one that selects an NPC/class specific gossip id (0xF for class 0x201 +
// player class 4, 0xB for 0x202 + 2, 0xA for 0x203 + 3, else pBank[0x1A] match -> 1, else 0)
// and passes flag 0 (NPCMENU_CainIdentifyCallback). Both are reached only as data from the callback
// table - 004b597c points here, 004b5956 points at 004b41e0.
BOOL __stdcall NPCMENU_ShowCurrentGossipCallback() {
    NPCMENU_SendCainIdentifyItems('\x01', gpNpcCurrentSpeech->nGossip);
    return 1;
}

int __stdcall NPCMENU_CainIdentifyCallback() {
    int nPlayerClass;
    D2UnitStrc* pPlayer = UNIT::Player::GetPlayerUnit_UI();
    if (!pPlayer) {
      nPlayerClass = -1;
    } else {
      nPlayerClass = pPlayer->nClassId;
    }
    if (_Interaction::bInteractingWithNpc) {
      int nNpcClass;
      pPlayer = UNIT::Player::UNITS_FindClientSideUnit(_Interaction::nCurrentInteractedNpcGUID, UNIT_MONSTER);
      if (pPlayer) {
        nNpcClass = pPlayer->nClassId;
        if (nNpcClass != 0x201) {
          if (nNpcClass != 0x202) {
            if (nNpcClass == 0x203 && nPlayerClass == 3) {
              NPCMENU_SendCainIdentifyItems('\0', 10);
              return 1;
            }
          } else {
            if (nPlayerClass == 2) {
              NPCMENU_SendCainIdentifyItems('\0', 0xb);
              return 1;
            }
          }
        } else {
          if (nPlayerClass == 4) {
            NPCMENU_SendCainIdentifyItems('\0', 0xf);
            return 1;
          }
        }
      }
    }
    if (nPlayerClass == gpNpcCurrentSpeech->pBank[1].nPlayerClass) {
      NPCMENU_SendCainIdentifyItems('\0', 1);
      return 1;
    }

    NPCMENU_SendCainIdentifyItems('\0', 0);
    return 1;
}

